const verboseFixture = `<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by Maven Help Plugin -->
<projects>
  <!-- Effective POM for project 'org.example:app:jar:1.0' -->
  <project xmlns="http://maven.apache.org/POM/4.0.0">
    <modelVersion>4.0.0</modelVersion>  <!-- org.example:app:${revision}, line 3 -->
    <parent>
      <groupId>org.example</groupId>  <!-- org.example:app:${revision}, line 5 -->
      <artifactId>root</artifactId>  <!-- org.example:app:${revision}, line 6 -->
      <version>1.0</version>  <!-- org.example:app:${revision}, line 7 -->
    </parent>
    <groupId>org.example</groupId>  <!-- org.example:root:1.0, line 4 -->
    <artifactId>app</artifactId>  <!-- org.example:app:${revision}, line 9 -->
    <dependencyManagement>
      <dependencies>
        <dependency>
          <groupId>org.example</groupId>  <!-- org.example:root:1.0, line 20 -->
          <artifactId>managed</artifactId>  <!-- org.example:root:1.0, line 21 -->
        </dependency>
      </dependencies>
    </dependencyManagement>
    <dependencies>
      <dependency>
        <groupId>org.example</groupId>  <!-- org.example:app:${revision}, line 12 -->
        <artifactId>lib</artifactId>  <!-- org.example:app:${revision}, line 13 -->
      </dependency>
      <dependency>
        <groupId>junit</groupId>  <!-- org.example:root:1.0, line 30 -->
        <artifactId>junit</artifactId>  <!-- org.example:root:1.0, line 31 -->
      </dependency>
    </dependencies>
    <modules>
      <module>sub</module>  <!-- org.example:app:${revision}, line 16 -->
    </modules>
    <build>
      <plugins>
        <plugin>
          <artifactId>maven-jar-plugin</artifactId>  <!-- org.example:root:1.0, line 40 -->
          <dependencies>
            <dependency>
              <artifactId>not-a-project-dep</artifactId>  <!-- org.example:app:${revision}, line 50 -->
            </dependency>
          </dependencies>
        </plugin>
      </plugins>
    </build>
  </project>
</projects>
`

func TestParseVerbose(t *testing.T) {
	ps, err := parseVerbose([]byte(verboseFixture))
	if err != nil {
		t.Fatal(err)
	}
	p := ps["org.example:app"]
	if p == nil {
		t.Fatalf("no project org.example:app in %v", ps)
	}
	if p.parentArt != "root" || p.parentLoc != (located{"org.example:app", 6}) {
		t.Errorf("parent = %q at %+v", p.parentArt, p.parentLoc)
	}
	want := []vdep{
		{ga: "org.example:lib", art: "lib", loc: located{"org.example:app", 13}},
		{ga: "junit:junit", art: "junit", loc: located{"org.example:root", 31}},
	}
	if !reflect.DeepEqual(p.deps, want) {
		t.Errorf("deps = %+v, want %+v (dependencyManagement and plugin dependencies are not the project's)", p.deps, want)
	}
	if !reflect.DeepEqual(p.modules, []vmod{{name: "sub", loc: located{"org.example:app", 16}}}) {
		t.Errorf("modules = %+v", p.modules)
	}
}

func TestParseLocation(t *testing.T) {
	for in, want := range map[string]located{
		" org.apache.dubbo:dubbo-parent:${revision}, line 195 ": {"org.apache.dubbo:dubbo-parent", 195},
		" org.apache:apache:38, line 41 ":                       {"org.apache:apache", 41},
	} {
		got, ok := parseLocation(in)
		if !ok || got != want {
			t.Errorf("parseLocation(%q) = %+v, %v; want %+v", in, got, ok, want)
		}
	}
	if _, ok := parseLocation(" Effective POM for project 'a:b:jar:1' "); ok {
		t.Error("a banner comment is no location")
	}
}

func TestRawLocations(t *testing.T) {
	src := []byte(`<?xml version="1.0"?>
<project>
  <parent>
    <groupId>org.example</groupId>
    <artifactId>root</artifactId>
  </parent>
  <artifactId>app</artifactId>
  <dependencies>
    <dependency>
      <groupId>org.example</groupId>
      <artifactId>lib</artifactId>
    </dependency>
  </dependencies>
  <modules>
    <module>sub</module>
  </modules>
  <profiles>
    <profile>
      <modules><module>extra</module></modules>
      <dependencies><dependency><artifactId>pdep</artifactId></dependency></dependencies>
    </profile>
  </profiles>
</project>
`)
	r, err := rawLocations(src)
	if err != nil {
		t.Fatal(err)
	}
	if r.parent != (rawLoc{"root", 5}) {
		t.Errorf("parent = %+v", r.parent)
	}
	if !reflect.DeepEqual(r.deps, []rawLoc{{"lib", 11}}) {
		t.Errorf("deps = %+v (a profile's dependencies are not the file's own)", r.deps)
	}
	if !reflect.DeepEqual(r.modules, []rawLoc{{"sub", 15}, {"extra", 19}}) {
		t.Errorf("modules = %+v", r.modules)
	}
}

func TestCutModule(t *testing.T) {
	src := []byte("<project>\n  <modules>\n    <module>a</module>\n    <module>b</module>\n  </modules>\n</project>\n")
	out, ok := cutModule(src, rawLoc{"b", 4})
	if !ok || string(out) != "<project>\n  <modules>\n    <module>a</module>\n    \n  </modules>\n</project>\n" {
		t.Errorf("cutModule = %q, %v", out, ok)
	}
	if _, ok := cutModule(src, rawLoc{"b", 3}); ok {
		t.Error("b is not written on line 3")
	}
}

func TestVerboseReferencesAttestByOwnModel(t *testing.T) {
	root := t.TempDir()
	pom := "<project>\n  <parent>\n    <artifactId>root</artifactId>\n  </parent>\n  <artifactId>app</artifactId>\n  <dependencies>\n    <dependency>\n      <artifactId>lib</artifactId>\n    </dependency>\n    <dependency>\n      <artifactId>gone</artifactId>\n    </dependency>\n  </dependencies>\n  <profiles><profile><dependencies>\n    <dependency><artifactId>lib</artifactId></dependency>\n  </dependencies></profile></profiles>\n</project>\n"
	if err := os.WriteFile(filepath.Join(root, "pom.xml"), []byte(pom), 0o644); err != nil {
		t.Fatal(err)
	}
	p := project{eff: effProject{coord: coord{GroupID: "g", ArtifactID: "app"}, Parent: coord{GroupID: "g", ArtifactID: "root"}}, file: reactorFile{Path: "pom.xml"}}
	vps := map[string]*vproj{"g:app": {group: "g", art: "app", parentArt: "root", parentLoc: located{"g:app", 3},
		// an active profile re-declares lib: Maven locates the effective one at line 15
		deps: []vdep{{ga: "g:lib", art: "lib", loc: located{"g:app", 15}}, {ga: "x:junit", art: "junit", loc: located{"g:root", 9}}}}}
	refs, _, c, err := verboseReferences(context.Background(), root, []project{p}, vps, nil, 1)
	if err != nil {
		t.Fatal(err)
	}
	want := []ref{{Path: "pom.xml", From: "app", To: "lib"}, {Path: "pom.xml", From: "app", To: "root"}}
	if !reflect.DeepEqual(refs, want) {
		t.Errorf("refs = %+v, want %+v (gone is not in the effective model; junit is the parent's)", refs, want)
	}
	if c.depNot != 1 || c.depOtherLine != 1 || c.parentAttested != 1 {
		t.Errorf("counts = %+v", c)
	}
}
